/**
 * @method
 * @name scwin.fn_init
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_init = async function () {
    scwin.data = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).dataArr_trust);
    if (!Array.isArray(scwin.data)) { console.warn('[sdd] 인쇄 데이터 부재(호스트 진입 필요) — jldfil35708'); return; }
    let gubun = scwin.data[11].calc_gubun;
    if (gubun === "1") {
        $c.util.getComponent("ipt_calcGubun").setValue("ETF");
        $c.util.getComponent('txt_tdNm4').setLabel("* 상장할 신탁원본액");
    } else {
        if (gubun === "2") {
            $c.util.getComponent("ipt_calcGubun").setValue("ETN");
            $c.util.getComponent('txt_tdNm4').setLabel("* 발행원본액");
        } else {
